        return arr[index];
    } else {
        return -1;
    }
}

int main() {
    int *arr = NULL; // Declare an array pointer
    int size, index, input;

    printf("Enter the size of the array: ");
    scanf("%d", &size);

    arr = (int*) malloc(size * sizeof(int)); // Allocate memory for the array

    if (!arr) {
        fprintf(stderr, "Memory allocation failed.\n");
        return 1;
    }

    for (int i = 0; i < size; ++i) {
        printf("Enter an integer for index %d: ", i);
        scanf("%d", &arr[i]);
    }

    printf("Enter the index of the value you want to get: ");
