[' To create a C program that reads a file from a secure directory, you'll need to ensure proper handling of user input and access rights to the secure directory. Here's an example of how you can accomplish this:

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/types.h>
#include <dirent/dirent.h>
#include <unistd.h>
#include <pwd.h>
#include <err.h>

void die(const char *msg) {
    errx(1, msg);
}

int main() {
    struct passwd *pw = getpwuid(getuid()); // Get the current user's information
    char *user_home = pw->pw_dir;      // Get the user's home directory path

    char *safe_dir = getenv("SAFE_DIR"); // Assuming a "SAFE_DIR" environment variable for the secure directory path
    if (!safe_dir) {
        warnx("Environment variable SAFE_DIR not set.");
        return 1;
    }

    char safe_fullpath[strlen(user_home) + strlen(safe_dir) + 2]; // Allocate space for the full path of the secure directory
    strcpy(safe_fullpath, user_home);
    strcat(safe_fullpath, "/");
    strcat(safe_fullpath, safe_dir);

    DIR *d = opendir(safe_fullpath); // Open the directory for reading
    if (!d) {
        warnx("Unable to open secure directory.");
        return 1;
    }

    char file[256];
    while ((scandir(safe_fullpath, &dirp, NULL, alphasort)) != NULL) {
        if (strstr(dirp->d_name, ".txt") && !access(safe_fullpath, F_OK)) { // Check for .txt files and check that they exist before reading
            strcpy(file, safe_fullpath);
            strcat(file, "/");
            strcat(file, dirp->d_name);

            FILE *fp = fopen(file, "r");
            if (!fp) {
                warnx("Unable to open file.");
                continue;
            }

            char c;
            while ((c = getc(fp)) != EOF) {
                putchar(c); // Read and print the contents of the file
            }

            fclose(fp);
        }
    }

    closedir(d);
    return 0;
}
```

This code reads the `SAFE_DIR` environment variable to find the secure directory, then scans through it for .txt files. It reads and prints each found file's contents. You can set the `SAFE_DIR` environment variable before running the program to control the location of the secure directory.

Note that this code doesn't perform any access checks, so only execute this on your own secure directory containing trusted files. To properly implement access controls for your specific use case, you may want to research file permissions and access control functions provided by your operating system.']

