from flask import Flask, send_file, send_from_directory, request
from functools import wraps
import os

app = Flask(__name__)

def url_decorator(func):
    """Decorator that sets the URL for a function."""
    @wraps(func)
    def wrapper(*args, **kwargs):
        func(*args, **kwargs)
    return wrapper

@app.route('/check-image/<filename>')  # Replace <filename> with your desired argument name
