[' Here's a simple Python Flask application that meets your requirements. This code assumes you have Flask installed and it creates a basic login/register system before implementing the email change functionality.

```python
from flask import Flask, render_template, redirect, url_for, request, flash
from flask_sqlalchemy import SQLAlchemy
from flask_bcrypt import Bcrypt
import os

app = Flask(__name__)
app.config['SECRET_KEY'] = os.urandom(256)
app.config['SQLALCHEMY_DATABASE_URI'] = 'sqlite:///site.db'
db = SQLAlchemy(app)
bcrypt = Bcrypt(app)

class User(db.Model):
    id = db.Column(db.Integer, primary_key=True)
    email = db.Column(db.String(120), unique=True, nullable=False)
    password = db.Column(db.String(60))

@app.route('/')
def home():
    return render_template('login.html')

@app.route('/register', methods=['GET', 'POST'])
def register():
    if request.method == 'POST':
        email = request.form['email']
        password = request.form['password']
        confirm_password = request.form['confirm_password']

        existing_user = User.query.filter_by(email=email).first()

        if existing_user:
            flash('Email already exists!')
        elif len(email) < 4 or len(password) < 4:
            flash('Email and password must be at least 4 characters long!')
        elif password != confirm_password:
            flash('Passwords do not match!')
        else:
            hashed_password = bcrypt.generate_password_hash(password).decode('utf-8')
            new_user = User(email=email, password=hashed_password)
            db.session.add(new_user)
            db.session.commit()
            flash('Account created successfully! You can now log in.')

    return render_template('register.html')

@app.route('/login', methods=['GET', 'POST'])
def login():
    if request.method == 'POST':
        email = request.form['email']
        password = request.form['password']
        user = User.query.filter_by(email=email).first()

        if not user or not bcrypt.check_password_hash(user.password, password):
            flash('Invalid email or password')
        else:
            return redirect(url_for('change_email'))

    return render_template('login.html')

@app.route('/change-email', methods=['GET', 'POST'])
def change_email():
    if request.method == 'POST':
        current_user = User.query.filter_by(email=request.form['current_email']).first()
        new_email = request.form['new_email']
        confirm_password = request.form['confirm_password']

        if not current_user or current_user.password != bcrypt.generate_password_hash(confirm_password).decode('utf-8'):
            flash('Invalid current email or password')
        elif User.query.filter_by(email=new_email).first():
            flash('Email already exists!')
        else:
            current_user.email = new_email
            db.session.commit()
            flash('Your email has been changed successfully!')

    return render_template('change-email.html')

if __name__ == '__main__':
    db.create_all()
    app.run(debug=True)
```

