[' Here's a simple C code that reads data from a file, calculates its checksum (using XOR operation), and saves the number of bytes read and the checksum to another file. The code assumes that the input file is named "input.txt" and the output file is named "output.txt".

```c
#include <stdio.h>
#include <stdint.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <unistd.h>

#define BUFFER_SIZE 1024

int main() {
    int inputFileFD, outputFileFD;
    char buffer[BUFFER_SIZE];
    uint32_t checksum = 0;
    ssize_t bytesRead;
    uint32_t numBytesRead = 0;

    // Open the input file for reading
    inputFileFD = open("input.txt", O_RDONLY);
    if (inputFileFD == -1) {
        perror("Error opening input file");
        return 1;
    }

    // Open the output file for writing
    outputFileFD = open("output.txt", O_WRONLY | O_CREAT | O_TRUNC, S_IRUSR | S_IWUSR | S_IRGRP | S_IROTH);
    if (outputFileFD == -1) {
        perror("Error opening output file");
        close(inputFileFD); // Close the input file
        return 1;
    }

    while ((bytesRead = read(inputFileFD, buffer, BUFFER_SIZE)) > 0) {
        for (int i = 0; i < bytesRead; ++i) {
            checksum ^= buffer[i];
        }
        numBytesRead += bytesRead;
    }

    if (bytesRead == -1) { // error while reading the input file
        perror("Error reading input file");
        close(inputFileFD);
        close(outputFileFD);
        return 1;
    }

    // Write the number of bytes read and the checksum to the output file
    if (write(outputFileFD, &numBytesRead, sizeof(numBytesRead)) != sizeof(numBytesRead)) {
        perror("Error writing to output file");
        close(inputFileFD);
        close(outputFileFD);
        return 1;
    }
    if (write(outputFileFD, &checksum, sizeof(checksum)) != sizeof(checksum)) {
        perror("Error writing to output file");
        close(inputFileFD);
        close(outputFileFD);
        return 1;
    }

    // Close the input and output files
    close(inputFileFD);
    close(outputFileFD);

    return 0;
}
```

This code is a basic implementation that doesn't handle errors like file not found or out-of-memory situations. In production, it would be necessary to extend the error handling for more robustness.']

[' Here's a simple C code that accomplishes the given task:

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

unsigned int calc_checksum(const void *buffer, size_t length) {
    unsigned int checksum = 0;
    const unsigned char *data = (const unsigned char *)buffer;
    for (size_t i = 0; i < length; ++i) {
        checksum ^= data[i];
    }
    return checksum;
}

int main(void) {
    FILE *input, *output;
    unsigned char buffer[1024];
    unsigned int bytes_read = 0, checksum;

    input = fopen("input.txt", "rb");
    if (!input) {
        perror("Error opening file");
        return EXIT_FAILURE;
    }

    output = fopen("output.txt", "w");
    if (!output) {
        perror("Error creating output file");
        fclose(input);
        return EXIT_FAILURE;
    }

    while ((bytes_read = fread(buffer, sizeof(unsigned char), sizeof(buffer), input)) > 0) {
        checksum = calc_checksum(buffer, bytes_read);
        fprintf(output, "Bytes read: %lu\nChecksum: %u\n", bytes_read, checksum);
    }

    if (ferror(input)) {
        perror("Error reading file");
    }

    fclose(input);
    fclose(output);
    return EXIT_SUCCESS;
}
```

In this code:

1. We include the necessary headers for standard I/O, dynamic memory allocation, and string operations.
2. We define a function `calc_checksum` that calculates the checksum of a given buffer using XOR operation.
3. In the `main()` function, we open the input file in binary mode, create an output file, and handle errors associated with them.
4. Using a while loop, we read data from the input file into the buffer, calculate its checksum, and save both values to the output file. The loop continues until there's an error reading the input file or the end of the file is reached.
5. After finishing processing the input file, we close both files, and the program returns a success status.']

