[' Here's a simple Flask web application that fulfills your requirements. I've used Flask, a popular Python micro-web framework, for this task.

```python
from flask import Flask, request, jsonify
app = Flask(__name__)

# Define our dictionary where we will store the data
data_dict = {}

@app.route('/api', methods=['GET'])
def api():
    # Get the payload from the URL
    payload_str = request.args.get('payload')

    if payload_str:
        try:
            # Load the payload into a dictionary
            data_dict = json.loads(payload_str)

            # Return the name value from the dictionary
            return jsonify({'name': data_dict.get('name', '')})
        except ValueError:
            return jsonify({'error': 'Invalid JSON payload.'}), 400
    else:
        return jsonify({'error': 'Payload parameter is missing.'}), 400

