[' Here's a C code implementation using both `system()` and `popen()` functions to execute the command `getent passwd <username>`. The code uses the standard input/output streams (`stdin`, `stdout`, and `stderr`) for communication with the executed command.

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>

int main(int argc, char **argv) {
    if (argc != 2) {
        printf("Usage: %s <username>\n", argv[0]);
        return -1;
    }

    // Using system() function
    int status;
    char command[128];
    sprintf(command, "getent passwd %s 2>&1", argv[1]);
    if (system(command) != 0) {
        perror("Error executing getent command");
        return -1;
    }

    // Using popen() function
    FILE *output = popen(command, "r");
    if (!output) {
        perror("Error opening pipe for getent command");
        return -1;
    }

    char buffer[256];
    size_t bytesRead;
    while ((bytesRead = getline(&buffer, sizeof(buffer), output)) != EOF) {
        printf("%s", buffer);
    }
    pclose(output);

    return 0;
}
```

You can compile the code using gcc:

```sh
$ gcc getent_user.c -o getent_user
```

Then run it with a specified username:

```sh
$ ./getent_user yourusername
```

This code reads the output of the command and prints it to the console. To store the output in a file, modify the last part as desired (e.g., redirecting the output to a file using `>`):

```sh
$ ./getent_user yourusername > userinfo.txt
```']

[' Here is a simple C program that fulfills your requirements:

```c
#include <stdio.h>
#include <stdlib.h>
#include <sys/types.h>
#include <unistd.h>
#include <string.h>
#include <sys/wait.h>
#include <errno.h>

int execute_command(char *cmd) {
    pid_t pid;
    int status;

    pid = fork();
    if (pid == -1) {
        perror("Fork failed");
        return 1;
    }

    if (pid == 0) { // Child process
        if (execvp(cmd, cmd) == -1) {
            perror("Command execution failed");
            _exit(1);
        }
    } else { // Parent process
        waitpid(pid, &status, 0);
        if (WIFEXITED(status)) {
            return WEXITSTATUS(status);
        }
    }
}

int main(int argc, char **argv) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s username\n", argv[0]);
        return 1;
    }

    const char *cmd = "/bin/cat /etc/passwd | /usr/bin/grep ";
    size_t cmdlen = strlen(cmd);
    size_t usrlen = strlen(argv[1]);

    char *fullcmd = malloc(cmdlen + usrlen + 2); // for spaces and null terminator
    strcpy(fullcmd, cmd);
    strcat(fullcmd, argv[1]);
    strcat(fullcmd, " ");
    strcat(fullcmd, argv[1]);

    if (execute_command(fullcmd) != 0) {
        return 1;
    }

    free(fullcmd);
    return 0;
}
```

This program takes one command line argument, the username. It constructs a command using `cat /etc/passwd | grep` followed by the given username and executes it using the `execute_command()` function. The error handling is kept minimal, but in a real-world scenario, you'd want to add more robustness, such as checking for command existence or memory allocation errors.']

[' Here's a simple C program that takes a username as a command line argument, runs the `id` command for that user, and prints the exit status of the command.

```c
#include <stdio.h>
#include <stdlib.h>
#include <sys/types.h>
#include <unistd.h>
#include <string.h>
#include <sys/wait.h>

int main(int argc, char *argv[]) {
    // Check if the correct number of arguments is provided
    if (argc != 2) {
        printf("Usage: %s <username>\n", argv[0]);
        return 1;
    }

    pid_t pid = fork();
    if (pid == -1) { // Error occurred
        perror("fork failed");
        return 1;
    } else if (pid == 0) { // Child process
        char command[128];
        sprintf(command, "id %s", argv[1]);
        if (execl("/bin/bash", "/bin/bash", "-c", command, NULL) == -1) { // Error occurred
            perror("exec failed");
            return 1;
        }
    } else { // Parent process
        int status;
        waitpid(pid, &status, 0);
        printf("Exit status: %d\n", WEXITSTATUS(status));
        return WEXITSTATUS(status);
    }
}
```

