#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>

void exec_ls(char* path) {
    FILE *pipe;
    char buffer[128];
    pipe = popen((path != NULL)? path : "ls", "r");
    if (pipe != NULL) {
        while (!feof(pipe)) {
            if (fgets(buffer, 128, pipe) != NULL)
                printf("%s", buffer);
        }
        pclose(pipe);
    }
}

