    if (argc != 2) {
        printf("Usage: ./program argument\n");
        return 1;
    }

    char* input = argv[1];
    int len = strlen(input);

    // Trim trailing whitespace
    for (int i = len - 1; i >= 0 && isspace(input[i]); --i) {
        input[i] = '\0';
        len -= 1;
    }

    // Trim newlines
    for (int i = 0; input[i]; ++i) {
        if (input[i] == '\n') {
            for (int j = i + 1; input[j]; ++j) {
                input[j - 1] = input[j];
            }
            len -= 1;
            input[len] = '\0';
        }
    }

    // Null terminate the string
    input[len] = '\0';

    printf("Trimmed argument: %s\n", input);

    return 0;
}
```

