void http_hello_page(request_rec *r) {
    char *body = NULL;  // Pointer to read request body
    int bodylen = 0;  // Length of the request body

    /* Read the request body */
    if (r->content_length != -1 && (body = APR_BRIGDE_alloc(r->connection->pool, r->content_length)) == NULL) {
        ap_log_error(APLOG_ERR, APLOG_MARK, r, "Could not allocate memory for request body");
        return;
    }

    if (apr_brigde_read(r->input_filters, body, r->content_length) != r->content_length) {
        ap_log_error(APLOG_ERR, APLOG_MARK, r, "Error reading request body");
        return;
    }

    /* Extract the username from the request body */
    if (apr_sscanf(body, "username=%s", username) != 1) {
        ap_log_error(APLOG_ERR, APLOG_MARK, r, "Invalid request format");
        return;
    }

    /* Construct the response body */
    snprintf(outputbuf, sizeof(outputbuf), "<html><body>Hello, %s!</body></html>", username);

    /* Write the response body to the output stream */
    apr_status_t status;
    apr_size_t size = strlen(outputbuf);
    void *buffer;

    buffer = apr_palloc(r->pool, size);
    memcpy(buffer, outputbuf, size);

    status = ap_rwrite(r, buffer, size, 0);
    if (status != APR_SUCCESS) {
        ap_log_error(APLOG_ERR, APLOG_MARK, r, "Error writing response body");
        return;
    }

    /* Close the output stream */
    apr_socket_t *sock = r->connection->output_filter->sockets[0];
    status = apr_socket_shutdown(sock, APR_SOCKET_SHUTDOWN_BOTH);
    if (status != APR_SUCCESS) {
        ap_log_error(APLOG_ERR, APLOG_MARK, r, "Error shutting down output stream");
        return;
    }
}

/* Register the http_hello_page callback */
void module_register(apr_pool_t *p) {
    ap_hook_handler(AP_METHOD_GET, http_hello_page, NULL, APR_HOOK_MIDDLE);
}
